// Spec: docs/superpowers/specs/2026-11-05-more-certs-design.md. SLES 16 facts checked against documentation.suse.com/sles/16.0.
// Outputs come from prototype/recorded/p15.js: openSUSE Leap 16.0 (zypper, supportconfig, Cockpit files), and an Ubuntu VM (Btrfs and snapper).
/* global cvAdd */
// p15Fixture() adds a practice copy of a supportconfig folder, Cockpit's list of refused users and a SLES style /etc/fstab.
function p15Fixture() {
  const fx = homeFixture();
  fx.dirs.push('/home/user/scc', '/etc/cockpit');
  fx.files.push(
    ['/home/user/scc/messages.txt', { content: 'Nov 05 08:00 systemd: Started cockpit.socket\nNov 05 08:02 sshd: Failed password for dana\nNov 05 08:05 kernel: I/O error on sda\nNov 05 08:06 kernel: I/O error on sda\nNov 05 08:07 chronyd: Selected source 10.0.0.1\nNov 05 08:09 kernel: I/O error on sda\n' }],
    ['/home/user/scc/basic-health-check.txt', { content: 'Disk /: 93% used\nMemory: 61% used\nFailed services: 1\n' }],
    ['/etc/cockpit/disallowed-users', { owner: 'root', content: 'root\n' }],
    ['/etc/fstab', { owner: 'root', content: 'UUID=1f2e-aa01 / btrfs defaults 0 0\nUUID=1f2e-aa01 /home btrfs subvol=/@/home 0 0\nUUID=1f2e-aa01 /.snapshots btrfs subvol=/@/.snapshots 0 0\nUUID=77aa-01bc /boot/efi vfat utf8 0 2\n' }],
  );
  return fx;
}
const p15Shown = (log, cmd) => { const r = new Shell(p15Fixture()).run(cmd), want = (r.out + r.err).trim(); return !!want && log.some(l => l.out.trim() === want); };
const p15Sudo = cmd => [cmd, `sudo ${cmd}`];

