  boss: { title: CHALLENGE, text: T('שרת SLES חדש, ודיסק שעושה בעיות.', 'A new SLES server, and a disk causing trouble.'), exercises: [
    { type: 'scenario', prompt: T('רעננו את רשימות החבילות', 'Update the package lists'), hint: T('ב־zypper, תת־הפקודה היא הפועל האנגלי ל"רעננו", כמו הכפתור בדפדפן.', 'With zypper, the subcommand is the English verb for reloading, like the browser button.'), accept: ['sudo zypper refresh', 'zypper refresh', 'zypper ref', 'sudo zypper ref'] },
    { type: 'scenario', prompt: T('התקינו את ה־pattern שנקרא cockpit', 'Install the pattern named cockpit'), hint: T('האפשרות ‎-t pattern', 'The option -t pattern'), accept: ['sudo zypper install -t pattern cockpit', 'zypper install -t pattern cockpit', 'zypper in -t pattern cockpit', 'sudo zypper in -t pattern cockpit'] },
    { type: 'output', prompt: T('על openSUSE Leap נבדקו ב־supportconfig ארבעה נושאים ברשימה של ‎-F‎. מה הודפס?', 'On openSUSE Leap four topics were looked up in the supportconfig -F list. What was printed?'), rec: 'sc-sc-f', wrongText: ['btrfs\nlvm\nnet\nselinux', 'supportconfig: invalid option -- F'] },
    { type: 'scenario', prompt: T('אספו עם supportconfig רק מידע על LVM', 'Use supportconfig to collect LVM information only'), hint: T('האפשרות ‎-i', 'The option -i'), accept: p15Sudo('supportconfig -i LVM') },
    { type: 'choice', prompt: T('שמרתם ארכיון של supportconfig ועומדים לשלוח אותו לתמיכה. מה בודקים קודם?', 'You have a supportconfig archive and are about to send it to support. What do you check first?'), plain: true,
      options: [T('שאין בו מידע פרטי שאסור לשלוח', 'That it holds no private data you may not send'), T('שהוא קטן מ־1MB', 'That it is under 1 MB'), T('ששם הקובץ באנגלית', 'That the file name is in English'), T('ש־SELinux כבוי', 'That SELinux is off')],
      why: [null, T('אין מגבלה כזו, והארכיון מכיל לוגים רבים.', 'There is no such limit, and the archive holds many logs.'), T('supportconfig קובעת את השם בעצמה.', 'supportconfig picks the name itself.'), T('אין קשר בין SELinux לשליחת הקובץ.', 'SELinux has nothing to do with sending the file.')] },
  ] },
