const UNIT_84 = {
  section: 10, unit: 84, exams: ['S6', 'S7'], title: T('Cockpit ושולחן עבודה מרוחק', 'Cockpit and remote desktop'), subtitle: T('התקנה, MFA, משתמשים ו־GNOME Remote Desktop', 'Installing, MFA, users and GNOME Remote Desktop'), color: 'blue', fixture: p15Fixture,
  lessons: [
    { title: T('להתקין ולהגיע', 'Install and reach it'), exercises: [
      { type: 'teach', cmd: 'cockpit.socket', name: 'web console', text: T('Cockpit הוא ממשק ניהול בדפדפן, והכלי שבא במקום YaST ב־SLES 16. מתקינים עם ‎zypper install cockpit‎ או, כמו במדריך של SUSE, עם ‎zypper install -t pattern cockpit‎. מפעילים עם ‎systemctl enable --now cockpit.socket‎. מפעילים socket ולא שירות: systemd מקשיב על פורט 9090 ומריץ את cockpit-ws רק כשמישהו מתחבר.', 'Cockpit is a management interface in the browser, and the tool that replaces YaST on SLES 16. Install it with zypper install cockpit or, like SUSE\'s guide, with zypper install -t pattern cockpit. Start it with systemctl enable --now cockpit.socket. You start a socket, not a service: systemd listens on port 9090 and runs cockpit-ws only when someone connects.') },
      { type: 'output', prompt: T('על openSUSE Leap הותקן Cockpit. בקובץ cockpit.socket של systemd חיפשו את השורה ListenStream. מה הודפס?', 'Cockpit was installed on openSUSE Leap. The ListenStream line was searched for in systemd\'s cockpit.socket file. What was printed?'), rec: 'sc-socket', wrongText: ['ListenStream=443', 'ListenStream=22'] },
      { type: 'sentence', prompt: READ, text: T('כדי להפעיל את Cockpit מפעילים ב־systemctl את היחידה ___.', 'To start Cockpit you enable the ___ unit with systemctl.'), options: ['cockpit.socket', 'cockpit-ws.service', 'cockpit.timer'], answer: 'cockpit.socket' },
      { type: 'scenario', prompt: T('הפעילו את Cockpit עכשיו וגם בכל אתחול', 'Start Cockpit now and on every boot'), hint: T('ב־systemctl: הפעולה שמפעילה בכל אתחול, עם הדגל שמפעיל גם עכשיו. בסוף יחידת ה־socket של Cockpit.', 'In systemctl: the action that starts at every boot, with the flag that starts it right away too. At the end the socket unit of Cockpit.'), accept: p15Sudo('systemctl enable --now cockpit.socket') },
      { type: 'output', prompt: T('על openSUSE Leap חיפשו בקובץ שמגדיר את השירות cockpit של firewalld את השם ואת הפורט. מה הודפס?', 'On openSUSE Leap, the file that defines firewalld\'s cockpit service was searched for its name and port. What was printed?'), rec: 'sc-fw-cockpit', wrongText: ['<short>Cockpit</short>\n<port protocol="tcp" port="443"/>', '<short>Cockpit</short>\n<port protocol="udp" port="9090"/>'] },
      { type: 'scenario', prompt: T('פתחו בחומת האש את השירות cockpit באופן קבוע (בלי reload)', 'Open the cockpit service in the firewall permanently (no reload)'), hint: T('ב־firewall-cmd: דגל אחד שהשינוי יהיה קבוע, ודגל שני שמוסיף שירות, עם שמו אחרי סימן שוויון.', 'In firewall-cmd: one flag to make the change lasting, and a second that adds a service, with its name after an equals sign.'), accept: [...p15Sudo('firewall-cmd --permanent --add-service=cockpit'), ...p15Sudo('firewall-cmd --add-service=cockpit --permanent')] },
      { type: 'choice', prompt: T('Cockpit פועל על שרת בכתובת 10.0.0.5, וחומת האש פתוחה. מה פותחים בדפדפן?', 'Cockpit runs on a server at 10.0.0.5, and the firewall is open. What do you open in the browser?'), options: ['https://10.0.0.5:9090', 'http://10.0.0.5:80', 'https://10.0.0.5:22', 'https://10.0.0.5:631'], answer: 'https://10.0.0.5:9090',
        why: { 'http://10.0.0.5:80': T('פורט 80 שייך לשרת אינטרנט רגיל.', 'Port 80 belongs to a normal web server.'), 'https://10.0.0.5:22': T('פורט 22 הוא SSH.', 'Port 22 is SSH.'), 'https://10.0.0.5:631': T('פורט 631 שייך ל־CUPS.', 'Port 631 belongs to CUPS.') } },
      { type: 'terminal', prompt: T('הקובץ /etc/cockpit/disallowed-users מכיל את המשתמשים שאסור להם להיכנס ל־Cockpit. הציגו אותו', 'The file /etc/cockpit/disallowed-users holds the users who may not log in to Cockpit. Show it'), hint: T('קובץ קטן קוראים עם cat. כתבו אחריה את הנתיב המלא, כמו שהוא במשימה.', 'Read a small file with cat. After it, write the full path, as it appears in the task.'), goal: (sh, log) => p15Shown(log, 'cat /etc/cockpit/disallowed-users'), solve: ['cat /etc/cockpit/disallowed-users'] },
      { type: 'choice', prompt: T('בקובץ הזה רשום root. אז איך מנהלים את השרת ב־Cockpit?', 'That file lists root. So how do you manage the server in Cockpit?'), plain: true,
        options: [T('נכנסים עם משתמש רגיל, ולוחצים Limited access כדי לקבל הרשאות ניהול', 'Log in as a regular user and click Limited access to get admin rights'), T('אי אפשר לנהל שרת ב־Cockpit', 'You cannot manage a server in Cockpit'), T('יוצרים סיסמה נפרדת רק ל־Cockpit', 'Make a separate password just for Cockpit'), T('נכנסים בלי סיסמה', 'Log in with no password')],
        why: [null, T('אפשר: הכניסה הרגילה מתחילה בהרשאות מוגבלות, ואפשר להעלות אותן.', 'You can: a normal login starts with limited access, and you can raise it.'), T('Cockpit משתמש בשמות ובסיסמאות של המשתמשים במערכת.', 'Cockpit uses the system\'s user names and passwords.'), T('תמיד נכנסים עם סיסמה או שיטת זיהוי אחרת.', 'You always log in with a password or another way to identify yourself.')] },
    ] },
    { title: T('הדפים ו־MFA', 'The pages and MFA'), exercises: [
      { type: 'teach', cmd: 'Cockpit pages', name: 'what each page does', text: T('בתפריט של Cockpit יש דף לכל נושא: Overview מציג את מצב השרת, Logs לוגים, Storage דיסקים, Networking רשת וחומת אש, Services שירותים ו־timers של systemd, Accounts משתמשים, ו־Terminal טרמינל בתוך הדפדפן. דפים של טכנולוגיות נוספות מופיעים רק אם הן קיימות בשרת.', 'Cockpit\'s menu has a page per topic: Overview shows the server\'s state, Logs logs, Storage disks, Networking network and firewall, Services systemd services and timers, Accounts users, and Terminal a terminal in the browser. Pages for extra technologies appear only if they exist on the server.') },
      { type: 'match', prompt: T('התאימו כל דף ב־Cockpit לתפקיד שלו', 'Match each Cockpit page to its job'), pairs: [['Overview', T('מצב כללי של השרת', 'the server\'s overall state')], ['Logs', T('סינון וקריאה של לוגים', 'filter and read logs')], ['Storage', T('מערכות קבצים, RAID ו־LVM', 'filesystems, RAID and LVM')], ['Networking', T('חומת אש וממשקי רשת', 'firewall and network interfaces')], ['Services', T('יחידות systemd', 'systemd units')]] },
      { type: 'choice', prompt: T('שירות נעצר, ואתם רוצים להפעיל אותו מהדפדפן. לאיזה דף נכנסים?', 'A service stopped and you want to start it from the browser. Which page do you open?'), options: ['Services', 'Accounts', 'Storage', 'Overview'], answer: 'Services',
        why: { Accounts: T('Accounts הוא למשתמשים.', 'Accounts is for users.'), Storage: T('Storage הוא לדיסקים.', 'Storage is for disks.'), Overview: T('Overview מציג מצב כללי, בלי ניהול של כל שירות.', 'Overview shows the overall state, not each service.') } },
      { type: 'sentence', prompt: READ, text: T('בדף ___ של Cockpit אפשר להריץ פקודות בתוך הדפדפן.', 'On Cockpit\'s ___ page you can run commands in the browser.'), options: ['Terminal', 'Logs', 'Overview'], answer: 'Terminal' },
      { type: 'teach', cmd: 'jeos-config otp', name: 'second factor', text: T('MFA מוסיף לסיסמה קוד מתחלף (TOTP) מאפליקציה בטלפון, כמו Google Authenticator או FreeOTP. כך גניבת סיסמה לא מספיקה. ב־SLES 16 מריצים ‎sudo /sbin/jeos-config otp‎, סורקים את הקוד באפליקציה ומאשרים עם מספר. מאותו רגע Cockpit דורש את הקוד. בשרת מי שבודק את הקוד הוא המודול pam_oath, והסוד נשמר בקובץ .pam_oath_usersfile בתיקיית הבית.', 'MFA adds to the password a changing code (TOTP) from a phone app, like Google Authenticator or FreeOTP. That way a stolen password is not enough. On SLES 16 you run sudo /sbin/jeos-config otp, scan the code in the app and confirm with a number. From then on Cockpit requires the code. On the server, the pam_oath module checks the code, and the secret is kept in the file .pam_oath_usersfile in the home folder.') },
      { type: 'output', prompt: T('על openSUSE Leap חיפשו בקובץ /usr/lib/pam.d/cockpit, שקובע איך נכנסים ל־Cockpit, את המודול שבודק את הקוד. מה הודפס?', 'On openSUSE Leap, /usr/lib/pam.d/cockpit, which decides how people log in to Cockpit, was searched for the MFA module. What was printed?'), rec: 'sc-pam', wrongText: ['pam_google_authenticator.so secret=/etc/secrets', 'pam_unix.so nullok'] },
      { type: 'scenario', prompt: T('הגדירו MFA למשתמש שלכם ב־SLES 16', 'Set up MFA for your user on SLES 16'), hint: T('משתמשים בכלי ההגדרות של JeOS, עם תת־פקודה של שלוש אותיות: קיצור של one-time password.', 'Use the JeOS configuration tool, with a three-letter subcommand: short for one-time password.'), accept: ['sudo /sbin/jeos-config otp', '/sbin/jeos-config otp', 'sudo jeos-config otp', 'jeos-config otp'] },
      { type: 'choice', prompt: T('הטלפון עם האפליקציה אבד, ואי אפשר להיכנס ל־Cockpit. מה עושים?', 'The phone with the app is lost, and you cannot log in to Cockpit. What do you do?'), plain: true,
        options: [T('נכנסים ב־SSH או במסוף ומריצים שוב את jeos-config otp, או מוחקים את .pam_oath_usersfile', 'Log in over SSH or at the console and run jeos-config otp again, or delete .pam_oath_usersfile'), T('מתקינים את השרת מחדש', 'Reinstall the server'), T('מכבים את חומת האש', 'Turn off the firewall'), T('מחכים שהקוד יפוג', 'Wait for the code to expire')],
        why: [null, T('אין צורך: MFA הזה חל על Cockpit, ו־SSH והמסוף עדיין עובדים.', 'No need: this MFA applies to Cockpit, and SSH and the console still work.'), T('חומת האש לא קשורה לזיהוי המשתמש.', 'The firewall has nothing to do with identifying the user.'), T('הקוד מתחלף כל הזמן, ועדיין צריך אותו.', 'The code keeps changing, and you still need it.')] },
    ] },
    { title: T('משתמשים: Cockpit ושורת פקודה', 'Users: Cockpit and the command line'), exercises: [
      { type: 'teach', cmd: 'Accounts', name: 'users in Cockpit', text: T('בדף Accounts של Cockpit, Create new account יוצר משתמש, ו־Create new group קבוצה. בלחיצה על משתמש אפשר לקבוע סיסמה, לחייב החלפה שלה (Force change), להוסיף מפתח SSH, לקבוע תפוגה ולמחוק. רק מי שקיבל הרשאות ניהול יכול לערוך משתמשים אחרים. הכול מגיע לאותם קבצים ש־useradd כותבת, אז זה אותו משתמש בשתי הדרכים.', 'On Cockpit\'s Accounts page, Create new account makes a user, and Create new group a group. Clicking a user lets you set a password, force changing it (Force change), add an SSH key, set an expiry date and delete. Only someone with admin rights can edit other users. It all lands in the same files useradd writes, so it is the same user either way.') },
      { type: 'output', prompt: T('על openSUSE Leap נוצרו הקבוצה devs והמשתמש dana. אחר כך הריצו ‎usermod -aG devs dana‎ ו־id. מה הודפס?', 'On openSUSE Leap the group devs and the user dana were created. Then usermod -aG devs dana and id ran. What was printed?'), rec: 'sc-useradd', wrongText: ['uid=1001(dana) gid=1002(dana) groups=1002(dana)', 'uid=1001(dana) gid=1001(devs) groups=1001(devs)'] },
      { type: 'sentence', prompt: READ, text: T('בלי ‎-a‎, הפקודה ‎usermod -G‎ ___ את הקבוצות הקודמות של המשתמש.', 'Without -a, usermod -G ___ the user\'s previous groups.'), options: ['replaces', 'keeps', 'locks'], answer: 'replaces' },
      { type: 'match', prompt: T('התאימו כל פעולה ב־Cockpit לפקודה שעושה אותו דבר', 'Match each Cockpit action to the command that does the same'), pairs: [['useradd -m', T('Create new account', 'Create new account')], ['groupadd', T('Create new group', 'Create new group')], ['passwd', T('Set password', 'Set password')], ['passwd -e', T('Force change', 'Force change')]] },
      { type: 'scenario', prompt: T('צרו את המשתמש noa, עם תיקיית בית', 'Create the user noa, with a home folder'), hint: T('הכלי useradd, עם הדגל שיוצר תיקיית בית, ואחריו שם המשתמשת.', 'The useradd tool, with the flag that creates a home folder, then the user name.'), accept: p15Sudo('useradd -m noa') },
      { type: 'scenario', prompt: T('הוסיפו את noa לקבוצה devs, בלי לאבד את הקבוצות שכבר יש לה', 'Add noa to the devs group, without losing the groups she already has'), hint: T('הכלי usermod, עם דגל של הוספה ודגל של קבוצות נוספות. אחר כך הקבוצה ואז המשתמשת.', 'The usermod tool, with an append flag and a flag for extra groups. Then the group and then the user.'), accept: [...p15Sudo('usermod -aG devs noa'), ...p15Sudo('usermod -a -G devs noa')] },
      { type: 'scenario', prompt: T('קבעו סיסמה למשתמש noa', 'Set a password for the user noa'), hint: T('הכלי שמחליף סיסמאות, ושמו הוא המילה password בלי כמה אותיות. אחריו שם המשתמשת.', 'The tool that changes passwords, whose name is the word password with a few letters missing. Then the user name.'), accept: p15Sudo('passwd noa') },
      { type: 'output', prompt: T('על openSUSE Leap קבעו ל־dana סיסמה, והריצו ‎passwd -S dana‎ (רק השם והמצב). האות P אומרת שיש סיסמה בשימוש. מה הודפס?', 'On openSUSE Leap dana got a password, then passwd -S dana ran (just the name and state). The letter P means a usable password is set. What was printed?'), rec: 'sc-passwd', wrongText: ['dana L', 'dana NP'] },
    ] },
    { title: T('GNOME Remote Desktop', 'GNOME Remote Desktop'), exercises: [
      { type: 'teach', cmd: 'GNOME Remote Desktop', name: 'a screen over RDP', text: T('GNOME Remote Desktop מציג את שולחן העבודה של השרת דרך RDP, בפורט 3389. אל השרת מתחברים מכל לקוח RDP, כמו gnome-connections או remmina. הוא דורש GNOME על Wayland, הגרפיקה היחידה ב־SLES 16. זה עובד גם בלי מסך: המשתמש מקבל את מסך הכניסה הרגיל.', 'GNOME Remote Desktop shows the server\'s desktop over RDP, on port 3389. You connect to it from any RDP client, like gnome-connections or remmina. It needs GNOME on Wayland, the only graphics on SLES 16. It works with no monitor attached too: the user gets the normal login screen.') },
      { type: 'choice', prompt: T('צריך לשנות שורה אחת בקובץ הגדרות בשרת רחוק, דרך קו איטי. במה תשתמשו?', 'You need to change one line in a settings file on a remote server, over a slow line. What do you use?'), options: ['ssh', 'GNOME Remote Desktop', 'CUPS', 'zypper'], answer: 'ssh',
        why: { 'GNOME Remote Desktop': T('מסך שלם דורש הרבה רוחב פס, ובשביל שורה אחת SSH מספיק.', 'A whole screen needs a lot of bandwidth, and SSH is enough for one line.'), CUPS: T('CUPS הוא מערכת ההדפסה.', 'CUPS is the printing system.'), zypper: T('zypper מתקין חבילות.', 'zypper installs packages.') } },
      { type: 'choice', prompt: T('מתי דווקא כדאי להשתמש ב־GNOME Remote Desktop?', 'When is GNOME Remote Desktop the right choice?'), plain: true,
        options: [T('כשצריך להפעיל תוכנה גרפית שאין לה גרסה לטרמינל', 'When you must run a graphical app that has no terminal version'), T('כשמריצים סקריפט בכל הלילה', 'When running a script every night'), T('כשמעתיקים קובץ לשרת', 'When copying a file to a server'), T('כשמריצים פקודה אחת', 'When running one command')],
        why: [null, T('את זה עושים עם cron או timer.', 'That is a job for cron or a timer.'), T('את זה עושים עם scp או rsync.', 'That is a job for scp or rsync.'), T('את זה עושים עם ssh.', 'That is a job for ssh.')] },
      { type: 'teach', cmd: 'grdctl', name: 'turn it on', text: T('מגדירים עם grdctl, בארבעה שלבים: ‎grdctl --system rdp set-tls-key‎ ו־set-tls-cert נותנים מפתח ותעודה להצפנה, ‎set-credentials‎ קובע את פרטי הכניסה ל־RDP, ו־‎enable‎ מפעיל. אחר כך ‎systemctl enable --now gnome-remote-desktop.service‎, ופותחים בחומת האש את השירות rdp. בהתחברות מקלידים קודם את פרטי ה־RDP, ואז במסך הכניסה את המשתמש שלכם.', 'You set it up with grdctl, in four steps: grdctl --system rdp set-tls-key and set-tls-cert give a key and certificate for encryption, set-credentials sets the RDP login details, and enable turns it on. Then systemctl enable --now gnome-remote-desktop.service, and open the rdp service in the firewall. When connecting you first type the RDP details, then your own user at the login screen.') },
      { type: 'output', prompt: T('על openSUSE Leap חיפשו בקובץ שמגדיר את השירות rdp של firewalld את השם ואת הפורט. מה הודפס?', 'On openSUSE Leap, the file that defines firewalld\'s rdp service was searched for its name and port. What was printed?'), rec: 'sc-fw-rdp', wrongText: ['<short>rdp</short>\n<port protocol="tcp" port="5900"/>', '<short>rdp</short>\n<port protocol="tcp" port="9090"/>'] },
      { type: 'sentence', prompt: READ, text: T('את GNOME Remote Desktop מגדירים עם הכלי ___.', 'You set up GNOME Remote Desktop with the ___ tool.'), options: ['grdctl', 'nmcli', 'snapper'], answer: 'grdctl' },
      { type: 'scenario', prompt: T('הפעילו את RDP במצב המערכת של grdctl', 'Enable RDP in grdctl\'s system mode'), hint: T('הכלי grdctl במצב המערכת, ואחריו הפרוטוקול והפועל האנגלי שפירושו "להפעיל".', 'The grdctl tool in system mode, then the protocol and the English verb for turning something on.'), accept: p15Sudo('grdctl --system rdp enable') },
      { type: 'scenario', prompt: T('הפעילו את השירות gnome-remote-desktop עכשיו וגם בכל אתחול', 'Start the gnome-remote-desktop service now and on every boot'), hint: T('ב־systemctl: הפעולה שמפעילה בכל אתחול, עם הדגל שמפעיל גם עכשיו, ואחריה שם השירות.', 'In systemctl: the action that starts at every boot, with the flag that starts it right away too, then the service name.'), accept: [...p15Sudo('systemctl enable --now gnome-remote-desktop.service'), ...p15Sudo('systemctl enable --now gnome-remote-desktop')] },
    ] },
  ],
  boss: { title: CHALLENGE, text: T('שרת SLES חדש בלי Cockpit, ועובדת חדשה בצוות.', 'A new SLES server with no Cockpit, and a new colleague on the team.'), exercises: [
    { type: 'scenario', prompt: T('התקינו את החבילה cockpit', 'Install the cockpit package'), hint: T('במנהל החבילות של SUSE: הפעולה שמתקינה, ואחריה שם החבילה.', 'With the SUSE package manager: the action that installs, then the package name.'), accept: ['sudo zypper install cockpit', 'zypper install cockpit', 'zypper in cockpit', 'sudo zypper in cockpit', 'sudo zypper install -t pattern cockpit', 'zypper install -t pattern cockpit', 'sudo zypper in -t pattern cockpit', 'zypper in -t pattern cockpit'] },
    { type: 'scenario', prompt: T('הפעילו את Cockpit עכשיו וגם בכל אתחול', 'Start Cockpit now and on every boot'), hint: T('ב־systemctl: הפעולה שמפעילה בכל אתחול, עם הדגל שמפעיל גם עכשיו. בסוף יחידת ה־socket של Cockpit.', 'In systemctl: the action that starts at every boot, with the flag that starts it right away too. At the end the socket unit of Cockpit.'), accept: p15Sudo('systemctl enable --now cockpit.socket') },
    { type: 'scenario', prompt: T('פתחו עכשיו בחומת האש את השירות cockpit, בלי ‎--permanent', 'Open the cockpit service in the firewall now, without --permanent'), hint: T('ב־firewall-cmd: הדגל שמוסיף שירות, עם שם השירות אחרי סימן שוויון.', 'In firewall-cmd: the flag that adds a service, with the service name after an equals sign.'), accept: p15Sudo('firewall-cmd --add-service=cockpit') },
    { type: 'scenario', prompt: T('צרו את המשתמשת maya עם תיקיית בית', 'Create the user maya with a home folder'), hint: T('הכלי useradd, עם הדגל שיוצר תיקיית בית, ואחריו שם המשתמשת.', 'The useradd tool, with the flag that creates a home folder, then the user name.'), accept: p15Sudo('useradd -m maya') },
    { type: 'scenario', prompt: T('הגדירו MFA ב־SLES 16', 'Set up MFA on SLES 16'), hint: T('הכלי ששמו מתחיל ב־jeos, ואחריו הקיצור של סיסמה חד־פעמית, שלוש אותיות.', 'The tool whose name starts with jeos, followed by the three-letter abbreviation for one-time password.'), accept: ['sudo /sbin/jeos-config otp', '/sbin/jeos-config otp', 'sudo jeos-config otp', 'jeos-config otp'] },
  ] },
};

const UNIT_85 = {
  section: 10, unit: 85, exams: ['S12', 'C1.3'], title: T('Btrfs ו־snapshots', 'Btrfs and snapshots'), subtitle: T('subvolumes, ‏snapper ושמות קבועים לדיסקים', 'Subvolumes, snapper and persistent device names'), color: 'purple', fixture: p15Fixture,
  lessons: [
    { title: T('Btrfs ו־subvolumes', 'Btrfs and subvolumes'), exercises: [
      { type: 'teach', cmd: 'btrfs', name: 'copy-on-write', text: T('Btrfs היא מערכת הקבצים של השורש ב־SLES. היא copy-on-write: שינוי נכתב למקום חדש, והישן נשאר. לכן snapshot הוא מיידי וכמעט לא תופס מקום. יוצרים אותה עם mkfs.btrfs. הפלטים ביחידה הוקלטו על מכונת Ubuntu ועל דיסק לתרגול בשם /dev/loop50, וכלי Btrfs זהים ב־SLES.', 'Btrfs is the root filesystem on SLES. It is copy-on-write: a change is written to a new place, and the old data stays. So a snapshot is instant and takes almost no space. You create it with mkfs.btrfs. The outputs in this unit were recorded on an Ubuntu machine with a practice disk named /dev/loop50, and the Btrfs tools are the same on SLES.') },
      { type: 'output', prompt: T('על דיסק לתרגול בגודל 2GB הריצו mkfs.btrfs עם התווית data. מה הודפס (מסונן)?', 'mkfs.btrfs ran with the label data on a 2 GB practice disk. What was printed (filtered)?'), rec: 'b-mkfs', wrongText: ['Label:              btrfs\nNode size:          16384\nFilesystem size:    2.00GiB', 'Creating filesystem with 524288 4k blocks\nWriting superblocks: done'] },
      { type: 'sentence', prompt: READ, text: T('Btrfs היא copy-on-write: שינוי נכתב למקום ___, והמידע הישן נשאר.', 'Btrfs is copy-on-write: a change is written to a ___ place, and the old data stays.'), options: ['new', 'same', 'temporary'], answer: 'new' },
      { type: 'teach', cmd: 'btrfs subvolume', name: 'subvolumes', text: T('subvolume נראה כמו תיקייה, אבל הוא עץ קבצים עצמאי בתוך אותה מערכת קבצים. הם חולקים את כל המקום הפנוי, בלי גדלים קבועים כמו מחיצות. ב־SLES הם קובעים מה ייכלל ב־snapshot: למשל ‎/home‎ הוא נפרד כדי שחזרה לאחור לא תמחק קבצים של משתמשים.', 'A subvolume looks like a folder, but it is an independent file tree inside the same filesystem. They share all the free space, with no fixed sizes like partitions. On SLES they decide what a snapshot includes: for example /home is separate so a rollback does not erase users\' files.') },
      { type: 'output', prompt: T('מערכת Btrfs מחוברת ב־/mnt/data, ועם ‎btrfs subvolume create‎ יצרו בה שני subvolumes: home ו־srv. מה הדפיסה ‎btrfs subvolume list /mnt/data‎?', 'A Btrfs filesystem is mounted at /mnt/data, and btrfs subvolume create made two subvolumes in it: home and srv. What did btrfs subvolume list /mnt/data print?'), rec: 'b-sub-list', wrongText: ['home\nsrv', 'ID 5 path /mnt/data'] },
      { type: 'scenario', prompt: T('צרו subvolume בשם backup בתוך ‎/mnt/data', 'Create a subvolume named backup inside /mnt/data'), hint: T('ב־btrfs: תת־הפקודה של subvolumes, הפעולה שיוצרת, ואז הנתיב המלא של החדש.', 'In btrfs: the subcommand for subvolumes, the action that creates, and then the full path of the new one.'), accept: p15Sudo('btrfs subvolume create /mnt/data/backup') },
      { type: 'output', prompt: T('ב־subvolume בשם home יש קובץ notes.txt. חיברו רק אותו ל־/mnt/h עם ‎-o subvol=home‎, והציגו את התיקייה ואת אפשרות החיבור. מה הודפס?', 'The subvolume named home holds a file notes.txt. Only it was mounted at /mnt/h with -o subvol=home, then the folder and the mount option were shown. What was printed?'), rec: 'b-sub-mount', wrongText: ['home\nsrv\nsubvol=/', 'notes.txt\nsubvol=/srv'] },
      { type: 'output', prompt: T('ב־df הרגילה קשה לראות מה קורה ב־Btrfs, כי יש לה בלוקים נפרדים לנתונים ולמטא־דאטה. מה הדפיסה ‎btrfs filesystem df /mnt/data‎?', 'Plain df makes Btrfs hard to read, because it has separate blocks for data and metadata. What did btrfs filesystem df /mnt/data print?'), rec: 'b-df', wrongText: ['Filesystem      Size  Used Avail Use% Mounted on\n/dev/loop50     2.0G  3.6M  1.8G   1% /mnt/data', 'Data: 2.00GiB\nFree: 1.78GiB'] },
      { type: 'output', prompt: T('‎btrfs filesystem usage‎ נותנת תמונה מלאה יותר של אותו דיסק לתרגול, בגודל 2GB: גודל, כמה הוקצה וכמה פנוי. מה הודפס (9 שורות ראשונות)?', 'btrfs filesystem usage gives a fuller picture of the same 2 GB practice disk: size, how much is allocated and how much is free. What was printed (first 9 lines)?'), rec: 'b-usage', wrongText: ['Overall:\n    Device size:   2.00GiB\n    Used:          2.00GiB\n    Free:          0.00B', 'Filesystem      Size  Used Avail Use%\n/dev/loop50     2.0G  3.6M  1.8G   1%'] },
    ] },
    { title: T('snapper: לצלם ולהשוות', 'snapper: take and compare'), exercises: [
      { type: 'teach', cmd: 'snapper', name: 'snapshot manager', text: T('snapper מנהל snapshots: צילומים של מערכת הקבצים בנקודת זמן. ב־SLES יש לו הגדרה בשם root ל־‎/‎, והיא ברירת המחדל. ‎snapper list‎ מציגה, ‎snapper create -d "text"‎ יוצרת עם תיאור. כאן הפעלנו אותו על הדיסק לתרגול, אחרי ‎snapper -c root create-config /mnt/data‎.', 'snapper manages snapshots: pictures of the filesystem at a point in time. On SLES it has a config named root for /, which is the default. snapper list shows them, snapper create -d "text" makes one with a description. Here we ran it on the practice disk, after snapper -c root create-config /mnt/data.') },
      { type: 'output', prompt: T('הקובץ /mnt/data/app.conf מכיל port=80. לפני שינוי יצרו snapshot עם ‎-p‎, שמדפיס את המספר שלו. מה הודפס?', 'The file /mnt/data/app.conf holds port=80. Before a change a snapshot was made with -p, which prints its number. What was printed?'), rec: 's-create', wrongText: ['0', 'Created snapshot'] },
      { type: 'output', prompt: T('יצרו שני snapshots: לפני שינוי הפורט ואחריו. מה הדפיסה ‎snapper list‎ עם שלוש עמודות?', 'Two snapshots were made: before and after changing the port. What did snapper list print with three columns?'), rec: 's-list1', wrongText: [' # | Type   | Description\n---+--------+------------\n0  | single | current    ', ' # | Type   | Description       \n---+--------+-------------------\n1  | single | before port change\n2  | single | after port change '] },
      { type: 'sentence', prompt: READ, text: T('ב־snapper list, השורה עם המספר ___ היא המערכת עכשיו.', 'In snapper list, the line numbered ___ is the system right now.'), options: ['0', '1', '2'], answer: '0' },
      { type: 'scenario', prompt: T('צרו snapshot עם התיאור before update', 'Create a snapshot with the description before update'), hint: T('ב־snapper: הפעולה שיוצרת, עם הדגל של תיאור. התיאור במירכאות, כי יש בו רווח.', 'In snapper: the action that creates, with the flag for a description. The description goes in quotes, because it has a space.'), accept: [...p15Sudo('snapper create -d "before update"'), ...p15Sudo('snapper create -d \'before update\''), ...p15Sudo('snapper create --description "before update"')] },
      { type: 'teach', cmd: 'snapper status', name: 'what changed', text: T('‎snapper status 1..2‎ מציגה אילו קבצים השתנו בין snapshot 1 ל־2, ו־‎snapper diff 1..2‎ מציגה מה השתנה בתוכם. ‎snapper undochange 1..2‎ מחזירה את הקבצים למצב שלהם ב־1, בלי אתחול. בתחילת השורה של status, האות c אומרת שהתוכן השתנה.', 'snapper status 1..2 shows which files changed between snapshots 1 and 2, and snapper diff 1..2 shows what changed inside them. snapper undochange 1..2 puts the files back to their state in 1, with no reboot. At the start of a status line, the letter c means the content changed.') },
      { type: 'output', prompt: T('בין snapshot 1 ל־2 שינו ב־/mnt/data/app.conf את port=80 ל־port=8080. מה הדפיסה ‎snapper status 1..2‎?', 'Between snapshots 1 and 2, /mnt/data/app.conf went from port=80 to port=8080. What did snapper status 1..2 print?'), rec: 's-status', wrongText: ['+..... /mnt/data/app.conf', '-..... /mnt/data/app.conf'] },
      { type: 'output', prompt: T('אותו שינוי ב־/mnt/data/app.conf. מה הדפיסה ‎snapper diff 1..2‎ (התאריכים הוסרו)?', 'The same change in /mnt/data/app.conf. What did snapper diff 1..2 print (dates removed)?'), rec: 's-diff', wrongText: ['--- /mnt/data/.snapshots/2/snapshot/app.conf\n+++ /mnt/data/.snapshots/1/snapshot/app.conf\n@@ -1 +1 @@\n-port=8080\n+port=80', 'c..... /mnt/data/app.conf'] },
      { type: 'output', prompt: T('עכשיו /mnt/data/app.conf מכיל port=8080. הציגו אותו, הריצו ‎snapper undochange 1..2‎, והציגו שוב. מה הודפס?', 'Now /mnt/data/app.conf holds port=8080. It was shown, then snapper undochange 1..2 ran, then it was shown again. What was printed?'), rec: 's-undo', wrongText: ['port=8080\ncreate:0 modify:1 delete:0\nport=8080', 'port=80\ncreate:1 modify:0 delete:0\nport=8080'] },
    ] },
    { title: T('חזרה לאחור', 'Rolling back'), exercises: [
      { type: 'teach', cmd: 'snapper rollback', name: 'go back in time', text: T('כשעדכון שובר את המערכת, undochange לא מספיקה: צריך להחזיר את כל השורש. בתפריט GRUB בוחרים את הרשומה של הצילומים (bootable snapshots), ואז את הצילום מלפני התקלה. המערכת עולה לקריאה בלבד. בודקים שהיא תקינה, מריצים ‎snapper rollback‎, ומאתחלים. אפשר גם בלי תפריט: ‎snapper rollback 5‎.', 'When an update breaks the system, undochange is not enough: the whole root has to go back. In the GRUB menu pick the bootable snapshots entry, then the snapshot from before the problem. The system boots read-only. Check it works, run snapper rollback, and reboot. You can also skip the menu: snapper rollback 5.') },
      { type: 'output', prompt: T('snapshot 1 הוא צילום של /mnt/data, ויושב בתיקייה .snapshots. ניסו ליצור בו קובץ חדש בשם x. מה הודפס?', 'Snapshot 1 is a picture of /mnt/data, and it lives in the .snapshots folder. Creating a new file named x in it was tried. What was printed?'), rec: 's-ro', wrongText: ['touch: cannot touch \'/mnt/data/.snapshots/1/snapshot/x\': Permission denied', 'x'] },
      { type: 'choice', prompt: T('אחרי עדכון השרת לא עולה כראוי. מה סדר הפעולות?', 'After an update the server does not come up properly. What is the order of actions?'), plain: true,
        options: [T('לאתחל מ־snapshot ב־GRUB, לבדוק, להריץ snapper rollback, לאתחל', 'Boot a snapshot from GRUB, check it, run snapper rollback, reboot'), T('להריץ snapper rollback, ורק אחר כך לחפש מה עבד', 'Run snapper rollback, and only then look for what worked'), T('למחוק את כל ה־snapshots ולאתחל', 'Delete every snapshot and reboot'), T('להריץ zypper update שוב ושוב', 'Run zypper update again and again')],
        why: [null, T('קודם בודקים שה־snapshot הזה באמת תקין.', 'First check that this snapshot really works.'), T('כך אין יותר לאן לחזור.', 'That leaves nothing to go back to.'), T('עדכון נוסף לא מחזיר את המצב הקודם.', 'Another update does not restore the previous state.')] },
      { type: 'sentence', prompt: READ, text: T('את המעבר הסופי ל־snapshot שבדקתם עושה הפקודה snapper ___.', 'The final move to the snapshot you checked is made by snapper ___.'), options: ['rollback', 'undochange', 'status'], answer: 'rollback' },
      { type: 'teach', cmd: 'pre and post', name: 'around zypper', text: T('ב־SLES, zypper יוצר לבד זוג snapshots סביב כל התקנה: pre לפני ו־post אחרי, עם קישור ביניהם. ב־SLES תיקיות כמו ‎/home‎, ‎/opt‎, ‎/srv‎, ‎/usr/local‎ ו־‎/tmp‎ הן מחוץ ל־snapshots, כדי שחזרה לאחור לא תמחק נתונים. לכן snapshot לא מחליף גיבוי.', 'On SLES, zypper creates a pair of snapshots around every install by itself: pre before and post after, linked together. On SLES folders like /home, /opt, /srv, /usr/local and /tmp stay out of snapshots, so a rollback does not erase data. That is why a snapshot does not replace a backup.') },
      { type: 'output', prompt: T('יצרו ביד זוג snapshots בשם zypper update, עם ‎-t pre‎ ו־‎-t post‎, בנוסף לשני הקודמים. מה הדפיסה ‎snapper list‎?', 'A pair of snapshots named zypper update was made by hand, with -t pre and -t post, besides the two earlier ones. What did snapper list print?'), rec: 's-prepost', wrongText: [' # | Type   | Pre # | Description  \n---+--------+-------+--------------\n0  | single |       | current      \n3  | pre    |     4 | zypper update\n4  | post   |       | zypper update', ' # | Type   | Pre # | Description  \n---+--------+-------+--------------\n0  | single |       | current      \n3  | single |       | zypper update\n4  | single |       | zypper update'] },
      { type: 'choice', prompt: T('עשיתם snapper rollback לשעה 08:00. מה קורה לקובץ שמשתמש שמר ב־‎/home‎ ב־09:00?', 'You ran snapper rollback to 08:00. What happens to a file a user saved in /home at 09:00?'), plain: true,
        options: [T('הוא נשאר, כי ‎/home‎ מחוץ ל־snapshots', 'It stays, because /home is outside snapshots'), T('הוא נמחק יחד עם השורש', 'It is erased along with the root'), T('הוא עובר ל־‎/tmp', 'It moves to /tmp'), T('הוא מקבל את השם x', 'It gets the name x')],
        why: [null, T('בדיוק בשביל זה ‎/home‎ הוא subvolume נפרד.', 'That is exactly why /home is a separate subvolume.'), T('הקובץ לא זז בכלל.', 'The file does not move at all.'), T('השם לא משתנה.', 'The name does not change.')] },
      { type: 'scenario', prompt: T('חזרו לאחור ל־snapshot מספר 5, בלי תפריט GRUB', 'Roll back to snapshot number 5, without the GRUB menu'), hint: T('ב־snapper: הפעולה שחוזרת לאחור, ואחריה מספר ה־snapshot.', 'In snapper: the action that goes back, then the snapshot number.'), accept: p15Sudo('snapper rollback 5') },
    ] },
    { title: T('שמות קבועים לדיסקים', 'Persistent device names'), exercises: [
      { type: 'teach', cmd: '/dev/disk/by-uuid', name: 'names that stay', text: T('השם sda תלוי בסדר שבו הליבה מצאה את הדיסקים, ולכן הוא יכול להשתנות באתחול. ב־/dev/disk יש קישורים עם שמות קבועים: by-uuid לפי המזהה של מערכת הקבצים, by-label לפי תווית, by-id לפי הדיסק עצמו (יצרן ומספר סידורי) ו־by-path לפי המיקום שבו הוא מחובר.', 'The name sda depends on the order in which the kernel found the disks, so it can change at boot. /dev/disk holds links with names that stay: by-uuid by the filesystem\'s ID, by-label by its label, by-id by the disk itself (maker and serial number) and by-path by where it is plugged in.') },
      { type: 'output', prompt: T('על מכונת Ubuntu הריצו ‎ls /dev/disk‎. מה הודפס?', 'ls /dev/disk was run on an Ubuntu machine. What was printed?'), rec: 'p-dirs', wrongText: ['sda\nsda1\nsda2', 'by-name\nby-size'] },
      { type: 'match', prompt: T('התאימו כל תיקייה ב־/dev/disk למה ששומר על השם', 'Match each folder in /dev/disk to what keeps the name'), pairs: [['by-uuid', T('המזהה של מערכת הקבצים', 'the filesystem\'s ID')], ['by-label', T('התווית שנתתם', 'the label you gave')], ['by-id', T('יצרן ומספר סידורי', 'maker and serial number')], ['by-path', T('המיקום של החיבור', 'where it is plugged in')]] },
      { type: 'output', prompt: T('על הדיסק לתרגול יש Btrfs עם התווית data. חיפשו אותו ב־/dev/disk/by-label. מה הודפס?', 'The practice disk has Btrfs with the label data. It was looked up in /dev/disk/by-label. What was printed?'), rec: 'p-label', wrongText: ['data -> /mnt/data', 'loop50 -> ../../data'] },
      { type: 'sentence', prompt: READ, text: T('ב־/etc/fstab משתמשים ב־UUID, כי השם ___ יכול להשתנות באתחול.', 'In /etc/fstab you use a UUID, because the name ___ can change at boot.'), options: ['sda', 'UUID', 'btrfs'], answer: 'sda' },
      { type: 'output', prompt: T('חיברו את הדיסק לתרגול כ־/dev/loop50, ואז ניתקו וחיברו אותו כ־/dev/loop60. השוו את ה־UUID לפני ואחרי, והציגו את הקישור by-label. מה הודפס?', 'The practice disk was attached as /dev/loop50, then detached and attached as /dev/loop60. The UUID before and after was compared and the by-label link shown. What was printed?'), rec: 'p-move', wrongText: ['UUID changed\ndata -> ../../loop60', 'same UUID\ndata -> ../../loop50'] },
      { type: 'terminal', prompt: T('הקובץ /etc/fstab כאן בנוי כמו ב־SLES: אותו UUID חוזר לכמה subvolumes. הציגו ממנו את השורות עם subvol', 'The file /etc/fstab here is built like on SLES: the same UUID repeats for several subvolumes. Show its lines with subvol'), hint: T('grep מציגה רק שורות שיש בהן המילה שחיפשתם. חפשו את המילה מהמשימה, ובסוף כתבו את נתיב הקובץ.', 'grep shows only the lines that contain the word you searched for. Search for the word from the task, and write the path of the file at the end.'), goal: (sh, log) => p15Shown(log, 'grep subvol /etc/fstab'), solve: ['grep subvol /etc/fstab'] },
      { type: 'terminal', prompt: T('ספרו כמה שורות ב־/etc/fstab משתמשות ב־UUID', 'Count how many lines in /etc/fstab use a UUID'), hint: T('הפעם הוסיפו ל־grep את ‎-c, שמדפיסה את מספר השורות. חפשו את המזהה שהמשימה מזכירה.', 'This time add -c to grep, which prints the number of lines. Search for the identifier the task mentions.'), ask: T('כמה שורות?', 'How many lines?'), goal: (sh, log) => p15Shown(log, 'grep -c UUID /etc/fstab'), solve: ['grep -c UUID /etc/fstab'] },
      { type: 'choice', prompt: T('החלפתם את הדיסק בדיסק חדש, עם אותו חיבור. איזה שם יישאר אותו דבר?', 'You replaced the disk with a new one on the same connector. Which name stays the same?'), options: ['by-path', 'by-id', 'by-uuid', 'by-label'], answer: 'by-path',
        why: { 'by-id': T('by-id כולל את המספר הסידורי של הדיסק הישן.', 'by-id includes the old disk\'s serial number.'), 'by-uuid': T('mkfs על הדיסק החדש יוצרת UUID חדש.', 'mkfs on the new disk makes a new UUID.'), 'by-label': T('התווית שייכת למערכת הקבצים הישנה, עד שתיתנו אותה שוב.', 'The label belongs to the old filesystem, until you give it again.') } },
    ] },
  ],
  boss: { title: CHALLENGE, text: T('עדכון מסוכן בשרת SLES: קודם מכינים דרך חזרה.', 'A risky update on a SLES server: first prepare a way back.'), exercises: [
    { type: 'scenario', prompt: T('צרו snapshot עם התיאור before kernel', 'Create a snapshot with the description before kernel'), hint: T('ב־snapper: הפעולה שיוצרת, עם הדגל של תיאור. התיאור במירכאות, כי יש בו רווח.', 'In snapper: the action that creates, with the flag for a description. The description goes in quotes, because it has a space.'), accept: [...p15Sudo('snapper create -d "before kernel"'), ...p15Sudo('snapper create -d \'before kernel\''), ...p15Sudo('snapper create --description "before kernel"')] },
    { type: 'scenario', prompt: T('הציגו אילו קבצים השתנו בין snapshot 7 ל־8', 'Show which files changed between snapshots 7 and 8'), hint: T('ב־snapper: הפעולה שמציגה מה השתנה. הטווח נכתב כשני המספרים עם שתי נקודות ביניהם.', 'In snapper: the action that shows what changed. The range is the two numbers with two dots between them.'), accept: p15Sudo('snapper status 7..8') },
    { type: 'scenario', prompt: T('החזירו את הקבצים האלה למצב שלהם ב־snapshot 7', 'Put those files back to their state in snapshot 7'), hint: T('ב־snapper: הפעולה שמבטלת שינויים. אחריה אותו טווח: שני המספרים עם שתי נקודות ביניהם.', 'In snapper: the action that reverses changes. Then the same range: the two numbers with two dots between them.'), accept: p15Sudo('snapper undochange 7..8') },
    { type: 'scenario', prompt: T('הציגו את ה־subvolumes של ‎/‎', 'Show the subvolumes of /'), hint: T('ב־btrfs: תת־הפקודה של subvolumes, הפעולה שמציגה רשימה, ואחריה הנתיב.', 'In btrfs: the subcommand for subvolumes, the action that prints a list, then the path.'), accept: p15Sudo('btrfs subvolume list /') },
    { type: 'scenario', prompt: T('הציגו איך מתחלק המקום ב־Btrfs של ‎/‎, בפירוט מלא', 'Show how space is split in the Btrfs of /, in full detail'), hint: T('ב־btrfs: תת־הפקודה של מערכת הקבצים, הפעולה שמציגה את ניצול המקום, ואחריה הנתיב.', 'In btrfs: the subcommand for the filesystem, the action that shows how space is used, then the path.'), accept: [...p15Sudo('btrfs filesystem usage /'), ...p15Sudo('btrfs fi usage /')] },
  ] },
};

COURSE.push(UNIT_83, UNIT_84, UNIT_85);

// 18: configuring vim
cvAdd(18, 3,
  { type: 'teach', cmd: '~/.vimrc', name: 'vim settings', text: T('vim קורא את ההגדרות שלו בכל פתיחה. הקובץ האישי הוא ‎~/.vimrc‎, והוא גובר על הקובץ של המערכת. כל שורה בו היא פקודה בלי נקודתיים: ‎set number‎ מציגה מספרי שורות, ו־‎syntax on‎ צובעת קוד. הקובץ לכל המשתמשים משתנה בין הפצות: ‎/etc/vimrc‎ ב־SUSE וב־Red Hat, ו־‎/etc/vim/vimrc‎ בדביאן. ‎vim --version‎ מראה מה נקרא.', 'vim reads its settings every time it opens. The personal file is ~/.vimrc, and it wins over the system file. Each line in it is a command without the colon: set number shows line numbers, and syntax on colors code. The file for all users differs between distributions: /etc/vimrc on SUSE and Red Hat, and /etc/vim/vimrc on Debian. vim --version shows what is read.') },
  { type: 'output', prompt: T('על openSUSE Leap חיפשו ב־‎vim --version‎ אילו קובצי vimrc נקראים. מה הודפס?', 'On openSUSE Leap, vim --version was searched for which vimrc files are read. What was printed?'), rec: 'sc-vim-files', wrongText: ['   system vimrc file: "/etc/vim/vimrc"\n     user vimrc file: "/etc/vimrc"', '   system vimrc file: "$HOME/.vimrc"\n     user vimrc file: "/etc/vimrc"'] },
  { type: 'choice', prompt: T('רוצים מספרי שורות לכל המשתמשים בשרת SUSE. באיזה קובץ כותבים?', 'You want line numbers for every user on a SUSE server. Which file do you write in?'), options: ['/etc/vimrc', '~/.vimrc', '/etc/fstab', '.bashrc'], answer: '/etc/vimrc',
    why: { '~/.vimrc': T('זה רק למשתמש שלכם.', 'That is only for your user.'), '/etc/fstab': T('זה קובץ של חיבור מחיצות.', 'That file is for mounting partitions.'), '.bashrc': T('זה קובץ של ה־shell, לא של vim.', 'That is a shell file, not a vim one.') } },
  { type: 'sentence', prompt: READ, text: T('כדי לראות מספרי שורות בכל פתיחה, כותבים ב־‎~/.vimrc‎ את השורה set ___.', 'To see line numbers every time, you write the line set ___ in ~/.vimrc.'), options: ['number', 'syntax', 'lines'], answer: 'number' },
  { type: 'terminal', prompt: T('צרו את הקובץ ‎.vimrc‎ בתיקיית הבית, עם שתי שורות: set number ו־syntax on', 'Create the file .vimrc in the home folder, with two lines: set number and syntax on'), hint: T('עם echo והסימן ‎>>‎ מוסיפים שורה לסוף קובץ, ואם הקובץ לא קיים הוא נוצר. עשו את זה פעמיים, פעם לכל שורה, עם הטקסט בתוך מרכאות.', 'With echo and the symbol >> you add a line to the end of a file, and if the file does not exist it is created. Do it twice, once for each line, with the text inside quotes.'), goal: sh => { const c = sh.files.get('/home/user/.vimrc')?.content || ''; return c.split('\n').includes('set number') && c.split('\n').includes('syntax on'); }, solve: ['echo "set number" >> .vimrc', 'echo "syntax on" >> .vimrc'] },
  { type: 'choice', prompt: T('מה ההבדל בין ‎:set number‎ בתוך vim לבין השורה ‎set number‎ ב־‎~/.vimrc‎?', 'What is the difference between :set number inside vim and the line set number in ~/.vimrc?'), plain: true,
    options: [T('בתוך vim זה רק עד היציאה, וב־‎~/.vimrc‎ זה בכל פתיחה', 'Inside vim it lasts until you quit, and in ~/.vimrc it applies every time'), T('אין שום הבדל', 'There is no difference'), T('‎~/.vimrc‎ חל על כל המשתמשים', '~/.vimrc applies to every user'), T('בתוך vim זה נשמר בקובץ שאתם עורכים', 'Inside vim it is saved into the file you are editing')],
    why: [null, T('יש: רק הקובץ נשאר אחרי היציאה.', 'There is: only the file lasts after you quit.'), T('‎~/.vimrc‎ הוא רק שלכם, ולכל המערכת יש קובץ אחר.', '~/.vimrc is only yours, and the system has another file.'), T('זו הגדרה של vim, לא טקסט בקובץ.', 'It is a vim setting, not text in the file.')] },
);

// 29: persistent names in fstab
cvAdd(29, 2,
  { type: 'teach', cmd: '/dev/disk/by-uuid', name: 'links by UUID', text: T('מה ש־blkid מדפיסה, ה־UUID, קיים גם כקישור: ב־/dev/disk/by-uuid יש קישור לכל מערכת קבצים, שמצביע על ההתקן שלה עכשיו. לכן השורה ‎UUID=…‎ ב־fstab ממשיכה לעבוד גם אם הדיסק נקרא היום sdb ואתמול sda.', 'What blkid prints, the UUID, also exists as a link: /dev/disk/by-uuid holds a link for every filesystem, pointing at its device right now. That is why the UUID=… line in fstab keeps working even if the disk is sdb today and was sda yesterday.') },
  { type: 'output', prompt: T('על דיסק לתרגול בשם /dev/loop50 יש Btrfs. חיפשו אותו ב־‎ls -l /dev/disk/by-uuid‎, וה־UUID הוחלף בתבנית. מה הודפס?', 'A practice disk named /dev/loop50 holds Btrfs. It was looked up in ls -l /dev/disk/by-uuid, with the UUID replaced by a placeholder. What was printed?'), rec: 'p-uuid', wrongText: ['loop50 -> ../../<uuid>', '<uuid> -> /mnt/data'] },
  { type: 'sentence', prompt: READ, text: T('הקישורים לפי מזהה של מערכת קבצים נמצאים ב־/dev/disk/___.', 'The links by filesystem ID are in /dev/disk/___.'), options: ['by-uuid', 'by-path', 'by-id'], answer: 'by-uuid' },
);
